args.sparql:
SELECT ?film ?director ?birth WHERE {
  VALUES ?film { dbr:Anatomy_of_Hell dbr:Metello }
  ?film dbo:director ?director .
  OPTIONAL {
    { ?director dbo:birthDate ?birth } UNION { ?director dbp:birthDate ?birth }
  }
}
ORDER BY ?film

